// ===== Save Store (Local Storage Manager) =====
const SaveStore = {
  key: "savedPlaces",

  load() {
    try {
      return JSON.parse(localStorage.getItem(this.key)) || {};
    } catch {
      return {};
    }
  },

  save(data) {
    localStorage.setItem(this.key, JSON.stringify(data));
  },

  has(name) {
    const data = this.load();
    return !!data[name];
  },

  add(name, status) {
    const data = this.load();
    data[name] = status;
    this.save(data);
  },

  remove(name) {
    const data = this.load();
    delete data[name];
    this.save(data);
  },

  getAll() {
    return this.load();
  },

  getByStatus(status) {
    const data = this.load();
    return Object.entries(data).filter(([_, s]) => s === status);
  }
};

// ===== Bottom Sheet Manager =====
class BottomSheetManager {
  constructor(sheetId, overlayId) {
    this.sheet = document.getElementById(sheetId);
    this.overlay = document.getElementById(overlayId);
    this.handle = this.sheet?.querySelector('.sheet-handle');
    this.isExpanded = false;
    this.isDragging = false;
    this.startY = 0;
    this.currentY = 0;
    this.initialHeight = 0;
    
    this.init();
  }

  init() {
    if (!this.sheet || !this.handle) return;

    // ── DRAG STRIP: full-width invisible hit area above the pill ──────────
    // Inject a wrapper div that spans the full width of the sheet so users
    // don't have to land precisely on the tiny 40px pill.
    this.dragStrip = document.createElement('div');
    this.dragStrip.className = 'sheet-drag-strip';
    // Insert it before the handle pill so it sits at the very top of the sheet
    this.sheet.insertBefore(this.dragStrip, this.sheet.firstChild);
    // Move the visual pill inside the strip
    this.dragStrip.appendChild(this.handle);

    // Bound callbacks stored so we can add/remove them per-drag
    this._boundTouchMove = this.onDragMove.bind(this);
    this._boundMouseMove = this.onDragMove.bind(this);
    this._boundTouchEnd  = this.onDragEnd.bind(this);
    this._boundMouseUp   = this.onDragEnd.bind(this);

    // Attach dragstart to the full-width strip (not just the pill)
    this.dragStrip.addEventListener('touchstart', this.onDragStart.bind(this), { passive: false });
    this.dragStrip.addEventListener('mousedown',  this.onDragStart.bind(this));

    // Click on strip (no drag) → toggle
    this.dragStrip.addEventListener('click', () => {
      if (!this.isDragging) this.toggle();
    });

    // Overlay click to collapse
    this.overlay?.addEventListener('click', () => this.collapse());

    // Initial state
    this.expand();
  }

  onDragStart(e) {
    this.isDragging = false; // set true after we confirm movement direction
    this._startY = e.type === 'touchstart' ? e.touches[0].clientY : e.clientY;
    this.initialHeight = this.sheet.offsetHeight;

    // Attach move/end listeners only while a drag is in progress
    document.addEventListener('touchmove', this._boundTouchMove, { passive: false });
    document.addEventListener('mousemove', this._boundMouseMove);
    document.addEventListener('touchend',  this._boundTouchEnd);
    document.addEventListener('mouseup',   this._boundMouseUp);
  }

  onDragMove(e) {
    const currentY = e.type === 'touchmove' ? e.touches[0].clientY : e.clientY;
    const moved = currentY - this._startY;

    // Only commit to dragging after 4px movement to avoid eating taps
    if (!this.isDragging) {
      if (Math.abs(moved) < 4) return;
      this.isDragging = true;
      this.sheet.style.transition = 'none'; // disable transition during live drag
    }

    if (e.cancelable) e.preventDefault();
    this.currentY = currentY;
    const deltaY = this.currentY - this.startY;
    
    // Calculate constraints
    const maxHeight =
    window.innerWidth >= 1024
        ? window.innerHeight
        : window.innerHeight * 0.82;
    const minHeight = parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--sheet-peek')) || 100;
    
    // New height based on drag (upward drag = smaller deltaY = larger height)
    const newHeight = this.initialHeight - deltaY;
    
    // Clamp to bounds
    const constrainedHeight = Math.max(minHeight, Math.min(newHeight, maxHeight));
    
    // Update max-height directly (no transform)
    this.sheet.style.maxHeight = `${constrainedHeight}px`;
  }

  onDragEnd() {
    // Always remove move/end listeners (attached on every dragStart)
    document.removeEventListener('touchmove', this._boundTouchMove);
    document.removeEventListener('mousemove', this._boundMouseMove);
    document.removeEventListener('touchend',  this._boundTouchEnd);
    document.removeEventListener('mouseup',   this._boundMouseUp);

    if (!this.isDragging) return; // was just a tap, not a drag
    
    this.isDragging = false;
    // Re-enable smooth transition for the snap animation
    this.sheet.style.transition = 'max-height var(--transition-slow) cubic-bezier(0.32, 0.72, 0, 1)';
    
    const deltaY = this.currentY - this._startY;
    const threshold = 40;
    
    // Calculate current position
    const viewportHeight = window.innerHeight;
    const maxExpanded =
    window.innerWidth >= 1024
        ? viewportHeight
        : viewportHeight * 0.85;
    const currentHeight = this.initialHeight - deltaY;
    
    // Determine closest snap point
    const peekHeight = parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--sheet-peek'));
    const midpoint = (maxExpanded + peekHeight) / 2;
    
    if (Math.abs(deltaY) > threshold) {
      if (deltaY > 0) {
        this.collapse();
      } else {
        this.expandToHeight(Math.min(currentHeight, maxExpanded));
      }
    } else {
      if (currentHeight > midpoint) {
        this.expandToHeight(Math.min(currentHeight, maxExpanded));
      } else {
        this.collapse();
      }
    }
    
    setTimeout(() => {
      this.sheet.style.transition = 'none';
    }, 400);
  }
  
  expandToHeight(height) {
    const maxHeight =
    window.innerWidth >= 1024
        ? window.innerHeight
        : window.innerHeight * 0.85;
    const constrainedHeight = Math.min(height, maxHeight);
    
    this.isExpanded = true;
    this.sheet.classList.remove('collapsed');
    this.sheet.classList.add('expanded');
    this.sheet.style.transform = '';
    this.sheet.style.maxHeight = `${constrainedHeight}px`;
    this.overlay?.classList.add('visible');
  }

  expand() {
    const maxHeight =
    window.innerWidth >= 1024
        ? window.innerHeight
        : window.innerHeight * 0.65;
    this.isExpanded = true;
    this.sheet.classList.remove('collapsed');
    this.sheet.classList.add('expanded');
    this.sheet.style.maxHeight = `${maxHeight}px`;
    this.sheet.style.transition = 'max-height var(--transition-slow) cubic-bezier(0.32, 0.72, 0, 1)';
    this.overlay?.classList.add('visible');
  }

  collapse() {
    const peekHeight = parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--sheet-peek')) || 100;
    this.isExpanded = false;
    this.sheet.classList.remove('expanded');
    this.sheet.classList.add('collapsed');
    this.sheet.style.maxHeight = `${peekHeight}px`;
    this.sheet.style.transition = 'max-height var(--transition-slow) cubic-bezier(0.32, 0.72, 0, 1)';
    this.overlay?.classList.remove('visible');
  }

  toggle() {
    if(window.innerWidth >= 1024){
      return;
    }
    if (this.isExpanded) {
      this.collapse();
    } else {
      this.expand();
    }
  }
}

// ===== Initialize on DOM Load =====
let bottomSheet;
let map;

window.addEventListener("DOMContentLoaded", () => {
  console.log("🌍 The P2V initializing...");

  const appLoader = document.getElementById("app-loading");
  appLoader?.classList.add("show");

  if (window.lucide) {
    lucide.createIcons();
  }

  bottomSheet = new BottomSheetManager('bottom-sheet', 'sheet-overlay');

  initMap();
  loadData();
  initSearch();
  initFilters();
  initModals();
  initNavigation();
  initProfile();
  initGPS();
  checkDeepLink();
  registerServiceWorker();
});

// ===== Map Initialization =====
function initMap() {
  map = L.map('map', { 
    zoomControl: false,
    attributionControl: true
  }).setView([28.6139, 77.209], 5);

  L.control.zoom({
    position: 'bottomright'
  }).addTo(map);

  L.tileLayer("https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png", {
    attribution: "&copy; OpenStreetMap"
  }).addTo(map);

  map.getContainer().addEventListener("wheel", e => {
    if (e.ctrlKey) e.preventDefault();
  }, { passive: false });

  const locateBtn = document.getElementById("locate-me");
  locateBtn?.addEventListener("click", () => {
    if (userLat && userLon) {
      map.flyTo([userLat, userLon], 14, { animate: true, duration: 1 });
      showToast("Centered on your location");
    } else {
      showToast("Location not available");
    }
  });

  window.map = map;

  // Intercept "Ask Nomad" link with leave-page confirmation
  const nomadBtn = document.getElementById('ai-chat-btn');
  if (nomadBtn) {
    nomadBtn.addEventListener('click', (e) => {
      e.preventDefault();
      const href = nomadBtn.getAttribute('href');
      confirmLeave({
        title: 'Open Nomad AI?',
        message: 'You\'ll be taken to the Nomad AI chat page.',
        confirmLabel: 'Open Nomad',
        onConfirm: () => { window.location.href = href; }
      });
    });
  }
}

// ===== GPS & Location =====
function initGPS() {
  getLocation();

  document.getElementById("retry-gps")?.addEventListener("click", () => {
    document.getElementById("gps-warning")?.classList.remove("show");
    getLocation();
  });
}

function getLocation() {
  if (!navigator.geolocation) {
    useFallbackLocation("Geolocation not supported");
    return;
  }

  let resolved = false;

  navigator.geolocation.getCurrentPosition(
    pos => {
      resolved = true;
      setUserLocation(pos.coords.latitude, pos.coords.longitude);
    },
    () => {
      navigator.geolocation.getCurrentPosition(
        pos => {
          resolved = true;
          setUserLocation(pos.coords.latitude, pos.coords.longitude);
        },
        () => {
          if (!resolved) useFallbackLocation("GPS timeout");
        },
        { enableHighAccuracy: true, timeout: 20000 }
      );
    },
    { enableHighAccuracy: false, timeout: 8000 }
  );
}

function setUserLocation(lat, lon) {
  userLat = lat;
  userLon = lon;
  hasRealGPS = true;

  if (!userMarker) {
    userMarker = L.marker([lat, lon], {
      icon: L.icon({
        iconUrl: 'data:image/svg+xml;base64,PHN2ZyB3aWR0aD0iMjQiIGhlaWdodD0iMjQiIHZpZXdCb3g9IjAgMCAyNCAyNCIgZmlsbD0ibm9uZSIgeG1sbnM9Imh0dHA6Ly93d3cudzMub3JnLzIwMDAvc3ZnIj48Y2lyY2xlIGN4PSIxMiIgY3k9IjEyIiByPSI4IiBmaWxsPSIjMDBBM0EzIi8+PGNpcmNsZSBjeD0iMTIiIGN5PSIxMiIgcj0iNCIgZmlsbD0id2hpdGUiLz48L3N2Zz4=',
        iconSize: [24, 24],
        iconAnchor: [12, 12]
      })
    }).addTo(map).bindPopup("📍 You are here");
  } else {
    userMarker.setLatLng([lat, lon]);
  }

  document.getElementById("gps-warning")?.classList.remove("show");
  map.setView([lat, lon], 12);
  applyFilters();
}

function useFallbackLocation(reason) {
  console.warn("Using fallback location:", reason);
  userLat = FALLBACK_LAT;
  userLon = FALLBACK_LON;
  hasRealGPS = false;

  const warning = document.getElementById("gps-warning");
  if (warning) {
    warning.classList.add("show");
    const textEl = document.getElementById("gps-warning-text");
    if (textEl) {
      textEl.textContent = `Unable to detect GPS. Showing places near ${FALLBACK_LABEL}.`;
    }
  }

  applyFilters();
}

// ===== Distance Calculation =====
function getDistance(lat1, lon1, lat2, lon2) {
  const R = 6371;
  const dLat = (lat2 - lat1) * Math.PI / 180;
  const dLon = (lon2 - lon1) * Math.PI / 180;
  const a = Math.sin(dLat / 2) ** 2 + 
            Math.cos(lat1 * Math.PI / 180) * 
            Math.cos(lat2 * Math.PI / 180) * 
            Math.sin(dLon / 2) ** 2;
  return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
}

function formatDistance(distanceKm) {
  if (!distanceKm) return "";
  
  if (hasRealGPS) {
    return `${distanceKm.toFixed(1)} km away`;
  }
  
  return `${distanceKm.toFixed(1)} km from ${FALLBACK_LABEL}`;
}

