async function loadData() {
  try {
    const snapshot = await db.collection("places").get();
    allPlaces = snapshot.docs.map(doc => doc.data());
    console.log(`✅ Loaded ${allPlaces.length} places`);
  } catch (err) {
    console.error("⚠️ Firebase fetch failed:", err);
    showToast("Failed to load places data");
  } finally {
    applyFilters();
    
    setTimeout(() => {
      isRestoringState = false;
      document.getElementById("app-loading")?.classList.remove("show");
    }, 800);
  }
}

// ===== Search Functionality =====
function initSearch() {
  const searchInput = document.getElementById("searchFilter");
  const clearBtn = document.getElementById("clear-search");

  if (!searchInput) return;

  searchInput.addEventListener("input", () => {
    const value = searchInput.value.trim();
    
    if (clearBtn) {
      clearBtn.style.display = value ? "flex" : "none";
    }

    clearTimeout(searchInput.searchTimeout);
    searchInput.searchTimeout = setTimeout(() => {
      applyFilters();
    }, 300);
  });

  clearBtn?.addEventListener("click", () => {
    searchInput.value = "";
    clearBtn.style.display = "none";
    applyFilters();
    showToast("Search cleared");
  });
}

// ===== Filter System =====
const ALL_POPULARITY = ["Priority", "Tier I", "Tier II", "Tier III", "Tier IV", "Tier V"];

let filters = {
  search: "",
  popularity: [...ALL_POPULARITY],
  distance: "All",
  status: ["All"]
};

function initFilters() {
  const savedFilters = localStorage.getItem("p2vFilters");
  if (savedFilters) {
    try {
      const parsed = JSON.parse(savedFilters);
      filters = { ...filters, ...parsed };
    } catch (e) {
      console.warn("Failed to parse saved filters");
    }
  }

  const popRow = document.getElementById("pop-row");
  popRow?.addEventListener("click", (e) => {
    if (!e.target.classList.contains("chip")) return;
    const val = e.target.dataset.val;

    if (val === "All") {
      filters.popularity = [...ALL_POPULARITY];
    } else {
      if (filters.popularity.includes(val)) {
        filters.popularity = filters.popularity.filter(v => v !== val);
        if (filters.popularity.length === 0) {
          filters.popularity = [...ALL_POPULARITY];
        }
      } else {
        filters.popularity.push(val);
      }
    }

    syncFilterUI();
    saveFilters();
    applyFilters();
  });

  const distRow = document.getElementById("dist-row");
  distRow?.addEventListener("click", (e) => {
    if (!e.target.classList.contains("chip")) return;
    filters.distance = e.target.dataset.val;
    syncFilterUI();
    saveFilters();
    applyFilters();
  });

  const statusRow = document.getElementById("status-row");
  statusRow?.addEventListener("click", (e) => {
    if (!e.target.classList.contains("chip")) return;
    const val = e.target.dataset.val;

    if (val === "All") {
      filters.status = ["All"];
    } else {
      filters.status = filters.status.filter(v => v !== "All");
      
      if (filters.status.includes(val)) {
        filters.status = filters.status.filter(v => v !== val);
      } else {
        filters.status.push(val);
      }

      if (filters.status.length === 0) {
        filters.status = ["All"];
      }
    }

    syncFilterUI();
    saveFilters();
    applyFilters();
  });

  document.getElementById("reset-filters")?.addEventListener("click", () => {
    filters = {
      search: "",
      popularity: [...ALL_POPULARITY],
      distance: "All",
      status: ["All"]
    };
    
    const searchInput = document.getElementById("searchFilter");
    if (searchInput) searchInput.value = "";
    
    syncFilterUI();
    saveFilters();
    applyFilters();
    showToast("Filters reset");
  });

  syncFilterUI();
}

function syncFilterUI() {
  document.querySelectorAll("#pop-row .chip").forEach(chip => {
    const val = chip.dataset.val;
    if (val === "All") {
      chip.classList.toggle("active", filters.popularity.length === ALL_POPULARITY.length);
    } else {
      chip.classList.toggle("active", filters.popularity.includes(val));
    }
  });

  document.querySelectorAll("#dist-row .chip").forEach(chip => {
    chip.classList.toggle("active", chip.dataset.val === filters.distance);
  });

  document.querySelectorAll("#status-row .chip").forEach(chip => {
    const val = chip.dataset.val;
    if (val === "All") {
      chip.classList.toggle("active", filters.status.includes("All"));
    } else {
      chip.classList.toggle("active", filters.status.includes(val));
    }
  });
}

function saveFilters() {
  localStorage.setItem("p2vFilters", JSON.stringify(filters));
}

// ===== Apply Filters & Render =====
const icons = {
  "Priority": L.icon({ iconUrl: "icons/red-marker.png", iconSize: [40, 40], iconAnchor: [, 42], popupAnchor: [0, -35] }),
  "Tier I": L.icon({ iconUrl: "icons/orange-marker.png", iconSize: [40, 40], iconAnchor: [14, 42], popupAnchor: [0, -35] }),
  "Tier II": L.icon({ iconUrl: "icons/yellow-marker.png", iconSize: [40, 40], iconAnchor: [14, 42], popupAnchor: [0, -35] }),
  "Tier III": L.icon({ iconUrl: "icons/green-marker.png", iconSize: [40, 40], iconAnchor: [14, 42], popupAnchor: [0, -35] }),
  "Tier IV": L.icon({ iconUrl: "icons/blue-marker.png", iconSize: [40, 40], iconAnchor: [14, 42], popupAnchor: [0, -35] }),
  "Tier V": L.icon({ iconUrl: "icons/purple-marker.png", iconSize: [40, 40], iconAnchor: [14, 42], popupAnchor: [0, -35] }),
  default: L.icon({ iconUrl: "icons/gray-marker.png", iconSize: [40, 40], iconAnchor: [14, 42], popupAnchor: [0, -35] })
};

function applyFilters() {
  markerIndex = {};
  
  if (userLat && userLon) {
    allPlaces.forEach(p => {
      if (p.Latitude && p.Longitude) {
        p.Distance = getDistance(userLat, userLon, parseFloat(p.Latitude), parseFloat(p.Longitude));
      } else {
        p.Distance = null;
      }
    });
  }

  const searchInput = document.getElementById("searchFilter");
  const searchTerm = searchInput?.value?.trim().toLowerCase() || "";

  markers.forEach(m => map.removeLayer(m));
  markers = [];
  activeMarker = null;

  let filtered = allPlaces.filter(place => {
    if (!filters.popularity.includes(place.Popularity)) return false;

    if (searchTerm) {
      const searchStr = `${place.Name} ${place.CountryState} ${place.Popularity}`.toLowerCase();
      if (!searchStr.includes(searchTerm)) return false;
    }

    if (filters.distance !== "All" && place.Distance) {
      if (place.Distance > parseFloat(filters.distance)) return false;
    }

    if (!filters.status.includes("All")) {
      const savedPlaces = SaveStore.load();
      const placeStatus = savedPlaces[place.Name];
      if (!placeStatus || !filters.status.includes(placeStatus)) return false;
    }

    return true;
  });

  if (userLat && userLon) {
    filtered.sort((a, b) => (a.Distance || Infinity) - (b.Distance || Infinity));
  }

  const countEl = document.getElementById("sheet-count");
  if (countEl) {
    countEl.textContent = `${filtered.length} place${filtered.length !== 1 ? 's' : ''}`;
  }

  renderPlaces(filtered.slice(0, 200));

  console.log(`✅ Displayed ${filtered.length} places`);
}

function renderPlaces(places) {
  const container = document.getElementById("card-container");
  if (!container) return;

  container.innerHTML = "";

  places.forEach(place => {
    const icon = icons[place.Popularity] || icons.default;
    const marker = L.marker([place.Latitude, place.Longitude], { icon }).addTo(map);

    const popupContent = createPopupContent(place);
    marker.bindPopup(popupContent, {
      maxWidth: 280,
      className: 'custom-popup'
    });

    marker.on("click", () => {
      openMarkerExclusively(marker);
      focusCard(place.Name);
    });

    markers.push(marker);
    markerIndex[place.Name] = marker;

    const card = createPlaceCard(place, marker);
    container.appendChild(card);
  });

  if (window.lucide) {
    lucide.createIcons();
  }
}

// ===== Leave-page Confirmation =====
// Shows a small modal before navigating away. onConfirm() fires if user taps "Go".
function confirmLeave({ title, message, confirmLabel, onConfirm }) {
  // Remove any existing confirm modal
  document.getElementById('leave-confirm-modal')?.remove();

  const modal = document.createElement('div');
  modal.id = 'leave-confirm-modal';
  modal.innerHTML = `
    <div class="leave-backdrop"></div>
    <div class="leave-box">
      <h3>${title}</h3>
      <p>${message}</p>
      <div class="leave-actions">
        <button class="leave-cancel btn-secondary">Stay</button>
        <button class="leave-go btn-primary">${confirmLabel || 'Go'}</button>
      </div>
    </div>
  `;

  document.body.appendChild(modal);
  // Trigger reflow so CSS transition plays
  requestAnimationFrame(() => modal.classList.add('show'));

  const close = () => {
    modal.classList.remove('show');
    setTimeout(() => modal.remove(), 250);
  };

  modal.querySelector('.leave-backdrop').addEventListener('click', close);
  modal.querySelector('.leave-cancel').addEventListener('click', close);
  modal.querySelector('.leave-go').addEventListener('click', () => {
    close();
    onConfirm();
  });
}

function createPopupContent(place) {
  const div = document.createElement('div');
  div.className = 'ptv-popup';

  const title = document.createElement('strong');
  title.textContent = place.Name;
  div.appendChild(title);

  const meta = document.createElement('div');
  meta.style.fontSize = '13px';
  meta.style.color = '#6B7280';
  meta.style.marginTop = '4px';
  meta.innerHTML = `${place.CountryState || 'Unknown'}<br>${place.Popularity}`;
  if (place.Distance) {
    meta.innerHTML += `<br>${formatDistance(place.Distance)}`;
  }
  div.appendChild(meta);

  const btnContainer = document.createElement('div');
  btnContainer.style.marginTop = '12px';
  btnContainer.style.display = 'flex';
  btnContainer.style.gap = '8px';

  const dirBtn = document.createElement('button');
  dirBtn.textContent = '🧭 Directions';
  dirBtn.onclick = () => confirmLeave({
    title: 'Open Google Maps?',
    message: `Get directions to <strong>${place.Name}</strong> in Google Maps.`,
    confirmLabel: 'Open Maps',
    onConfirm: () => openDirections(place.Latitude, place.Longitude, place.Name)
  });
  btnContainer.appendChild(dirBtn);

  const shareBtn = document.createElement('button');
  shareBtn.textContent = '🔗 Share';
  shareBtn.onclick = () => sharePlace(place);
  btnContainer.appendChild(shareBtn);

  div.appendChild(btnContainer);

  return div;
}

function createPlaceCard(place, marker) {
  const card = document.createElement('div');
  card.className = 'place-card';
  card.dataset.name = place.Name;

  const title = document.createElement('h3');
  title.textContent = place.Name;
  card.appendChild(title);

  const meta = document.createElement('div');
  meta.className = 'place-meta';
  meta.innerHTML = `
    <span><i data-lucide="map-pin"></i>${place.CountryState || 'Unknown'}</span>
    <span><i data-lucide="star"></i>${place.Popularity}</span>
    ${place.Distance ? `<span><i data-lucide="navigation"></i>${formatDistance(place.Distance)}</span>` : ''}
  `;
  card.appendChild(meta);

  const actions = document.createElement('div');
  actions.className = 'place-actions';

  const detailsBtn = document.createElement('button');
  detailsBtn.innerHTML = '<i data-lucide="file-text"></i><span>Details</span>';
  detailsBtn.onclick = (e) => {
    e.stopPropagation();
    if (place.slug) {
      confirmLeave({
        title: 'View place details?',
        message: `You'll be taken to the details page for <strong>${place.Name}</strong>.`,
        confirmLabel: 'View Details',
        onConfirm: () => { window.location.href = `/place/${place.slug}/`; }
      });
    }
  };
  actions.appendChild(detailsBtn);

  const dirBtn = document.createElement('button');
  dirBtn.innerHTML = '<i data-lucide="navigation"></i><span>Directions</span>';
  dirBtn.onclick = (e) => {
    e.stopPropagation();
    confirmLeave({
      title: 'Open Google Maps?',
      message: `Get directions to <strong>${place.Name}</strong> in Google Maps.`,
      confirmLabel: 'Open Maps',
      onConfirm: () => openDirections(place.Latitude, place.Longitude, place.Name)
    });
  };
  actions.appendChild(dirBtn);

  const shareBtn = document.createElement('button');
  shareBtn.innerHTML = '<i data-lucide="share-2"></i><span>Share</span>';
  shareBtn.onclick = (e) => {
    e.stopPropagation();
    sharePlace(place);
  };
  actions.appendChild(shareBtn);

  const saveBtn = document.createElement('button');
  saveBtn.className = 'save-btn';
  const isSaved = SaveStore.has(place.Name);
  saveBtn.innerHTML = isSaved 
    ? '<i data-lucide="heart"></i><span>Saved</span>'
    : '<i data-lucide="heart"></i><span>Save</span>';
  if (isSaved) saveBtn.classList.add('saved');
  
  saveBtn.onclick = (e) => {
    e.stopPropagation();
    handleSaveClick(place.Name, saveBtn);
  };
  actions.appendChild(saveBtn);

  card.appendChild(actions);

  card.onclick = () => {
    openMarkerExclusively(marker);
    highlightCard(card);
  };

  return card;
}

function highlightCard(card) {
  card.classList.add('card-highlight');
  card.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
  setTimeout(() => card.classList.remove('card-highlight'), 600);
}

function focusCard(placeName) {
  const card = document.querySelector(`.place-card[data-name="${CSS.escape(placeName)}"]`);
  if (card) {
    highlightCard(card);
  }
}

function openMarkerExclusively(marker) {
  if (activeMarker && activeMarker !== marker) {
    activeMarker.closePopup();
  }

  const isMobile = window.innerWidth < 768;

  if (isMobile) {
    // ── ONLY THIS BLOCK CHANGED ──────────────────────────────────────────
    // Visible map area on mobile:
    //   top edge    ~70px  (floating search bar height)
    //   bottom edge ~window.innerHeight - sheetPeekHeight
    // We want the marker to sit at ~40% from the top of that visible strip,
    // which keeps the popup comfortably below the search bar.
    const sheetPeek = parseFloat(
      getComputedStyle(document.documentElement).getPropertyValue('--sheet-peek')
    ) || 260;

    const mapTop    = 70;                                    // search bar clearance (px)
    const mapBottom = window.innerHeight - sheetPeek;        // top of the sheet peek
    const visibleMidY = mapTop + (mapBottom - mapTop) * 0.40; // 40% down the visible strip

    // Where should the marker pixel land after panning?
    const targetPoint  = L.point(map.getSize().x / 2, visibleMidY);
    const markerPoint  = map.latLngToContainerPoint(marker.getLatLng());

    const dx = markerPoint.x - targetPoint.x;
    const dy = markerPoint.y - targetPoint.y;

    map.panBy([dx, dy], { animate: true, duration: 0.8 });
    // ── END OF CHANGE ────────────────────────────────────────────────────
  } else {
    map.flyTo(marker.getLatLng(), 14, { animate: true, duration: 0.8 });
  }

  setTimeout(() => {
    marker.openPopup();
    activeMarker = marker;
  }, 500);
}

// ===== Actions =====
window.openDirections = function(lat, lon, name) {
  try {
    gtag && gtag('event', 'get_directions', {
      event_category: 'engagement',
      event_label: name
    });
  } catch(e) {}

  const url = `https://www.google.com/maps/dir/?api=1&destination=${lat},${lon}`;
  window.open(url, "_blank", "noopener,noreferrer");
};

window.sharePlace = async function(place) {
  const url = `${location.origin}/place/${place.slug || place.Name}/`;
  const text = `${place.Name} — Found on The P2V`;

  try {
    if (navigator.share) {
      await navigator.share({ title: place.Name, text, url });
      showToast("Shared successfully");
    } else if (navigator.clipboard) {
      await navigator.clipboard.writeText(url);
      showToast("Link copied to clipboard");
    }
  } catch (err) {
    console.error("Share failed:", err);
  }
};

// ===== Modals =====
function initModals() {
  const filterBtn = document.getElementById("filter-btn");
  const filterModal = document.getElementById("filter-modal");
  const closeFilter = document.getElementById("close-filter");

  filterBtn?.addEventListener("click", () => {
    filterModal?.classList.add("show");
  });

  closeFilter?.addEventListener("click", () => {
    filterModal?.classList.remove("show");
  });

  filterModal?.querySelector('.modal-backdrop')?.addEventListener("click", () => {
    filterModal.classList.remove("show");
  });

  const statusModal = document.getElementById("status-modal");
  const cancelStatus = document.getElementById("cancel-status");
  const doneStatus = document.getElementById("done-status");

  cancelStatus?.addEventListener("click", () => {
    statusModal?.classList.remove("show");
    window.pendingSaveName = null;
  });

  doneStatus?.addEventListener("click", () => {
    if (!window.pendingSaveName) return;

    const selectedStatus = document.querySelector('input[name="visitStage"]:checked')?.value;
    if (!selectedStatus) return;

    SaveStore.add(window.pendingSaveName, selectedStatus);
    showToast(`Saved as "${selectedStatus}"`);
    
    statusModal?.classList.remove("show");
    window.pendingSaveName = null;
    
    applyFilters();
  });

  statusModal?.querySelector('.modal-backdrop')?.addEventListener("click", () => {
    statusModal.classList.remove("show");
    window.pendingSaveName = null;
  });

  const feedbackBtn = document.getElementById("feedback-btn");
  const feedbackModal = document.getElementById("feedback-modal");
  const cancelFeedback = document.getElementById("cancel-feedback");
  const submitFeedback = document.getElementById("submit-feedback");
  const feedbackText = document.getElementById("feedback-text");

  feedbackBtn?.addEventListener("click", () => {
    feedbackModal?.classList.add("show");
  });

  cancelFeedback?.addEventListener("click", () => {
    feedbackModal?.classList.remove("show");
  });

  submitFeedback?.addEventListener("click", async () => {
    const text = feedbackText?.value?.trim();
    if (!text) {
      showToast("Please write something");
      return;
    }

    submitFeedback.disabled = true;
    submitFeedback.textContent = "Sending...";

    try {
      await fetch("https://script.google.com/macros/s/AKfycbzqmvWJUOGbFtO02ddkRr3e5_hgn-QmgqnY2ycPyIbxwmuHP9gmBDfD9nK3XDa5diIw3A/exec", {
        method: "POST",
        mode: "no-cors",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          message: text,
          timestamp: new Date().toISOString(),
          userLocation: { lat: userLat, lon: userLon }
        })
      });

      showToast("Feedback sent successfully!");
      feedbackText.value = "";
      feedbackModal?.classList.remove("show");
    } catch (err) {
      console.error("Feedback error:", err);
      showToast("Failed to send feedback");
    } finally {
      submitFeedback.disabled = false;
      submitFeedback.textContent = "Send";
    }
  });
}

function handleSaveClick(placeName, button) {
  if (SaveStore.has(placeName)) {
    SaveStore.remove(placeName);
    button.innerHTML = '<i data-lucide="heart"></i><span>Save</span>';
    button.classList.remove('saved');
    showToast("Removed from Saved");
    
    if (window.lucide) lucide.createIcons();
  } else {
    window.pendingSaveName = placeName;
    document.getElementById("status-modal")?.classList.add("show");
  }
}

// ===== Navigation =====
function initNavigation() {
  const navItems = document.querySelectorAll(".nav-item");
  const views = document.querySelectorAll(".app-view");

  navItems.forEach(item => {
    item.addEventListener("click", (e) => {
      const target = item.dataset.target;
      if (!target) return;

      e.preventDefault();

      navItems.forEach(i => i.classList.remove("active"));
      item.classList.add("active");

      views.forEach(view => {
        const isActive = view.dataset.view === target;
        view.hidden = !isActive;
        view.classList.toggle("is-active", isActive);
      });

      if (target === "home" && map) {
        setTimeout(() => map.invalidateSize(), 100);
      }

      if (target === "saved") {
        renderSavedTab();
      }
    });
  });
}

// ===== Saved Tab =====
window.renderSavedTab = function() {
  const listEl = document.getElementById("saved-list");
  const emptyEl = document.getElementById("saved-empty");
  const filterSelect = document.getElementById("saved-status-filter");

  if (!listEl || !emptyEl) return;

  const saved = SaveStore.load();
  let entries = Object.entries(saved);

  const selectedStatus = filterSelect?.value || "All";
  if (selectedStatus !== "All") {
    entries = entries.filter(([_, status]) => status === selectedStatus);
  }

  listEl.innerHTML = "";

  if (entries.length === 0) {
    emptyEl.classList.remove("hidden");
    return;
  }

  emptyEl.classList.add("hidden");

  entries.forEach(([name, status]) => {
    const place = allPlaces.find(p => p.Name === name);
    
    const card = document.createElement("div");
    card.className = "saved-card";
    
    card.innerHTML = `
      <div class="saved-top">
        <h3>${name}</h3>
        <span class="saved-status">${status}</span>
      </div>
      <div class="saved-actions">
        <button class="go-btn" data-name="${name}">
          <i data-lucide="map-pin"></i> View on Map
        </button>
        <button class="remove-btn" data-name="${name}">
          <i data-lucide="trash-2"></i> Remove
        </button>
      </div>
    `;

    card.querySelector(".go-btn").addEventListener("click", () => {
      if (!place) {
        showToast("Place not found");
        return;
      }

      document.querySelector('[data-target="home"]')?.click();

      setTimeout(() => {
        const marker = markerIndex[name];
        if (marker) {
          openMarkerExclusively(marker);
        } else {
          map.flyTo(marker.getLatLng(), 14, { animate: true, duration: 0.6 });
        }
      }, 300);
    });

    card.querySelector(".remove-btn").addEventListener("click", () => {
      SaveStore.remove(name);
      showToast("Removed from Saved");
      renderSavedTab();
      applyFilters();
    });

    listEl.appendChild(card);
  });

  if (window.lucide) {
    lucide.createIcons();
  }
};

document.getElementById("saved-status-filter")?.addEventListener("change", renderSavedTab);

// ===== Profile =====
function initProfile() {
  document.getElementById("clear-local-data")?.addEventListener("click", () => {
    if (!confirm("This will clear all saved data. Continue?")) return;
    
    localStorage.clear();
    showToast("Data cleared. Reloading...");
    
    setTimeout(() => location.reload(), 1200);
  });

  fetch('/manifest.json')
    .then(r => r.json())
    .then(manifest => {
      const versionEl = document.getElementById('app-version');
      if (versionEl && manifest.version) {
        versionEl.textContent = manifest.version;
      }
    })
    .catch(() => {});
}

// ===== Toast Notifications =====
function showToast(message, duration = 2000) {
  const toast = document.getElementById("toast");
  if (!toast) return;

  toast.textContent = message;
  toast.classList.add("show");

  setTimeout(() => {
    toast.classList.remove("show");
  }, duration);
}

// ===== Deep Link Handler =====
function checkDeepLink() {
  try {
    const params = new URLSearchParams(location.search);
    const slug = params.get("place");
    const lat = params.get("lat");
    const lon = params.get("lon");

    if (lat && lon) {
      pendingDeepLink = {
        type: "coords",
        lat: parseFloat(lat),
        lon: parseFloat(lon),
        slug
      };
    } else if (slug) {
      pendingDeepLink = {
        type: "slug",
        slug
      };
    }

    if (pendingDeepLink) {
      window.history.replaceState({}, document.title, "/");
      setTimeout(handleDeepLink, 1500);
    }
  } catch (err) {
    console.warn("Deep link error:", err);
  }
}

function handleDeepLink() {
  if (!pendingDeepLink) return;

  const { slug } = pendingDeepLink;
  if (!slug) return;

  const place = allPlaces.find(p => (p.slug || "").toLowerCase() === slug.toLowerCase());
  if (!place) {
    console.warn("Deep link place not found:", slug);
    return;
  }

  const marker = markerIndex[place.Name];
  if (marker) {
    openMarkerExclusively(marker);
    focusCard(place.Name);
  }

  pendingDeepLink = null;
}

// ===== Service Worker =====
function registerServiceWorker() {
  if ("serviceWorker" in navigator) {
    navigator.serviceWorker
      .register("./service-worker.js")
      .then(reg => console.log("✅ Service Worker registered"))
      .catch(err => console.error("❌ SW registration failed:", err));

    navigator.serviceWorker.addEventListener("message", event => {
      if (event.data?.type === "NEW_VERSION_AVAILABLE") {
        const toast = document.getElementById("update-toast");
        if (toast) {
          toast.classList.add("show");
          
          document.getElementById("refresh-app")?.addEventListener("click", () => {
            location.reload();
          });
        }
      }
    });
  }
}

// ===== Splash Screen =====
window.addEventListener("load", () => {
  setTimeout(() => {
    const splash = document.getElementById("splash-screen");
    if (splash) {
      splash.classList.add("fade-out");
      setTimeout(() => splash.style.display = "none", 600);
    }
  }, 1500);
});

// ===== Prevent Back Navigation Issues =====
window.addEventListener("popstate", () => {
  const activeView = document.querySelector(".app-view.is-active");
  if (!activeView || activeView.dataset.view !== "home") {
    document.querySelector('[data-target="home"]')?.click();
  }
});